@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipments in real-time, anywhere in the world.</p>

    <div class="row mt-4">
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Track a Shipment</h5>
                    <p class="card-text">Enter your tracking number to check shipment status and estimated delivery.</p>
                    <div class="input-group">
                        <input type="text" class="form-control" placeholder="e.g. SHP-20260709-12345"
                               @bind="trackingInput" @bind:event="oninput"
                               @onkeydown="HandleKeyDown" />
                        <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
                    </div>
                    @if (!string.IsNullOrEmpty(errorMessage))
                    {
                        <div class="alert alert-warning mt-2">@errorMessage</div>
                    }
                </div>
            </div>
        </div>
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Dispatcher Portal</h5>
                    <p class="card-text">Manage all shipments, update statuses, and create new shipments.</p>
                    <AuthorizeView>
                        <Authorized>
                            <a href="shipments" class="btn btn-success">View All Shipments</a>
                        </Authorized>
                        <NotAuthorized>
                            <a href="Account/Login" class="btn btn-outline-primary">Login to Access</a>
                        </NotAuthorized>
                    </AuthorizeView>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
