@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]

<PageTitle>Shipments - Dispatcher Dashboard</PageTitle>

<div class="container">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>Shipments</h2>
        <button class="btn btn-primary" @onclick="() => showCreateForm = true">+ New Shipment</button>
    </div>

    <!-- Filter controls -->
    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-secondary" @onclick="LoadShipments">Refresh</button>
        </div>
    </div>

    @if (isLoading)
    {
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Destination</td>
                            <td>@s.RecipientName</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>
                                <div class="btn-group btn-group-sm">
                                    <select class="form-select form-select-sm" style="width: auto;"
                                            value="@s.Status"
                                            @onchange="(e) => UpdateStatus(s, e)">
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@status" selected="@(s.Status == status)">@status</option>
                                        }
                                    </select>
                                </div>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <div class="alert alert-info">No shipments match your filters.</div>
        }
    }

    @if (showCreateForm)
    {
        <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Create New Shipment</h5>
                        <button type="button" class="btn-close" @onclick="() => showCreateForm = false"></button>
                    </div>
                    <div class="modal-body">
                        <div class="mb-3">
                            <label class="form-label">Origin</label>
                            <input type="text" class="form-control" @bind="newShipment.Origin" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Destination</label>
                            <input type="text" class="form-control" @bind="newShipment.Destination" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Recipient Name</label>
                            <input type="text" class="form-control" @bind="newShipment.RecipientName" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Customer Email</label>
                            <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Estimated Delivery</label>
                            <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                        <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
                            @(isCreating ? "Creating..." : "Create Shipment")
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private bool showCreateForm;
    private bool isCreating;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(statusFilter) &&
            Enum.TryParse<ShipmentStatus>(statusFilter, out var filterStatus) &&
            s.Status != filterStatus)
            return false;

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            return s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                   s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                   s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase);
        }
        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = false;
        isCreating = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}
