                            <label class="form-label">Estimated Delivery</label>
                            <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                        <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
                            @(isCreating ? "Creating..." : "Create Shipment")
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private bool showCreateForm;
    private bool isCreating;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(statusFilter) &&
            Enum.TryParse<ShipmentStatus>(statusFilter, out var filterStatus) &&
            s.Status != filterStatus)
            return false;

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            return s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                   s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                   s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase);
        }
        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = false;
        isCreating = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}

