                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    private string trackingInput = string.Empty;
    private string? errorMessage;

    private void TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingInput))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }
        errorMessage = null;
        Navigation.NavigateTo($"track/{Uri.EscapeDataString(trackingInput.Trim())}");
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

